MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception) {
  assert(image_info != (ImageInfo *) NULL);
  assert(image_info->signature == MagickCoreSignature);
  assert(images != (Image *) NULL);
  assert(images->signature == MagickCoreSignature);
  (void) exception;

  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  clone_info = CloneImageInfo(image_info);
  status = SetImageProgress(images, SaveImagesProgress, 0, 0);
  if (clone_info->adjoin != MagickFalse)
    for (image = images; image != (Image *) NULL; image = GetNextImageInList(image))
    {
      char
        *unique_filename;

      unique_filename = CloneString(filename);
      (void) FormatMagickPath(unique_filename, MAGICK_PATH_MAX, "%s", unique_filename);
      status = WriteImage(clone_info, image, unique_filename, exception);
      unique_filename = DestroyString(unique_filename);
      if (status == MagickFalse)
        break;
      status = SetImageProgress(images, SaveImagesProgress, 1, 0);
    }
  else
    status = WriteImage(clone_info, images, filename, exception);
  clone_info = DestroyImageInfo(clone_info);
  return(status);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception)
{
  assert(image_info != (const ImageInfo *) NULL);
  assert(image_info->signature == MagickSignature);
  assert(images != (Image *) NULL);
  assert(images->signature == MagickSignature);
  assert(exception != (ExceptionInfo *) NULL);
  assert(exception->signature == MagickSignature);

  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  register ssize_t
    i;

  status = MagickTrue;
  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return MagickFalse;
  if (images->adjoin != MagickFalse)
    {
      char
        **filenames;

      ssize_t
        number_images;

      number_images = GetImageListLength(images);
      filenames = (char **) AcquireQuantumMemory((size_t) number_images,
        sizeof(char *));
      if (filenames == (char **) NULL)
        {
          clone_info = DestroyImageInfo(clone_info);
          return MagickFalse;
        }
      (void) FormatMagickStringClone(filenames[0], MagickPathMax, "%s", filename);
      for (i=1; i < number_images; i++)
      {
        char
          *temp_filename;

        temp_filename = (char *) AcquireQuantumMemory(MagickPathMax, sizeof(char));
        if (temp_filename == (char *) NULL)
          {
            clone_info = DestroyImageInfo(clone_info);
            for (i=0; i < number_images; i++)
              if (filenames[i] != (char *) NULL)
                filenames[i] = (char *) RelinquishMagickMemory(filenames[i]);
            return MagickFalse;
          }
        (void) FormatMagickStringClone(temp_filename, MagickPathMax, "%s", filename);
        filenames[i] = temp_filename;
      }
      for (i=0; i < number_images; i++)
      {
        image = GetImageFromList(images, i);
        if (image == (Image *) NULL)
          {
            clone_info = DestroyImageInfo(clone_info);
            for (i=0; i < number_images; i++)
              if (filenames[i] != (char *) NULL)
                filenames[i] = (char *) RelinquishMagickMemory(filenames[i]);
            return MagickFalse;
          }
        image->scene = (size_t) i + 1;
        status &= WriteImage(clone_info, image, filenames[i], exception);
      }
      for (i=0; i < number_images; i++)
        filenames[i] = (char *) RelinquishMagickMemory(filenames[i]);
      filenames = (char **) RelinquishQuantumMemory(filenames);
    }
  else
    status = WriteImage(clone_info, images, filename, exception);
  clone_info = DestroyImageInfo(clone_info);
  return status;
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception) {
  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  assert(image_info != (ImageInfo *) NULL);
  assert(image_info->signature == MagickSignature);
  assert(images != (Image *) NULL);
  assert(images->signature == MagickSignature);
  assert(filename != (char *) NULL);
  assert(exception != (ExceptionInfo *) NULL);
  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return (MagickFalse);
  status = MagickTrue;
  GetPathComponent(filename, TailPath, clone_info->filename, NULL);
  image = images;
  do {
    ssize_t
      scene;

    scene = 0;
    (void) FormatLocaleString(clone_info->filename, MAGICK_PATH_MAX, "%s", filename);
    if (clone_info->adjoin != MagickFalse)
      (void) FormatLocaleString(clone_info->filename, MAGICK_PATH_MAX, "%s", filename);
    if (clone_info->adjoin != MagickFalse)
      status = WriteImage(clone_info, image, exception);
    else
      status = WriteImage(clone_info, image, exception);
    if (status == MagickFalse)
      break;
    if (clone_info->adjoin == MagickFalse)
      break;
    image = GetNextImageInList(image);
  } while (image != (Image *) NULL);
  clone_info = DestroyImageInfo(clone_info);
  return (status);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception) {
  assert(image_info != (ImageInfo *) NULL);
  assert(image_info->signature == MagickSignature);
  assert(images != (Image *) NULL);
  assert(exception != (ExceptionInfo *) NULL);
  assert(exception->signature == MagickSignature);

  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  size_t
    scene;

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return (MagickBooleanType) MagickFalse;

  status = MagickTrue;
  if (clone_info->adjoin != MagickFalse)
    for (image = images; image != (Image *) NULL; image = GetNextImageInList(image))
    {
      char
        *temp_filename;

      temp_filename = NULL;
      if (image->scene != 0)
        temp_filename = GetImageFilename(clone_info, image->scene, exception);
      else
        temp_filename = GetImageFilename(clone_info, 0, exception);
      if (temp_filename == (char *) NULL)
      {
        status = MagickFalse;
        continue;
      }
      (void) CopyMagickString(clone_info->filename, temp_filename,
                              sizeof(clone_info->filename));
      status &= WriteImage(clone_info, image, exception);
      scene = image->scene;
      if (scene == 0)
        scene = 1;
      (void) SetImageProgress(images, WriteImageTag, (MagickRealType) scene,
                                (MagickRealType) GetImageListLength(images));
    }
  else
    status = WriteImage(clone_info, images, exception);

  clone_info = DestroyImageInfo(clone_info);
  return status;
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception) {
  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  assert(image_info != (ImageInfo *) NULL);
  assert(image_info->signature == MagickSignature);
  assert(images != (Image *) NULL);
  assert(images->signature == MagickSignature);
  assert(filename != (char *) NULL);
  assert(exception != (ExceptionInfo *) NULL);
  clone_info = CloneImageInfo(image_info);
  status = MagickTrue;
  GetPathComponent(filename, TailPath, clone_info->filename, NULL);
  GetPathComponent(filename, DirectoryPath, clone_info->base_directory, NULL);
  clone_info->adjoin = MagickFalse;
  if (images->next == (Image *) NULL)
    clone_info->adjoin = MagickTrue;
  if ((clone_info->adjoin != MagickFalse) && (images->scene != 0))
    {
      Image
        *images_head;

      images_head = images;
      clone_info->adjoin = MagickFalse;
      image = images;
      while (image != (Image *) NULL)
      {
        if (image != images)
          clone_info->scene = image->scene;
        else
          clone_info->scene = 0;
        if (image->scene != 0)
          {
            Image
              *next;

            next = image->next;
            status = WriteImage(clone_info, image, exception);
            if (status != MagickFalse)
              {
                ssize_t
                  count;

                count = FormatImageFilename(clone_info, image, clone_info->filename,
                                            MagickPathExtent, exception);
                if (count <= 0)
                  status = MagickFalse;
              }
            if (status != MagickFalse)
              {
                status = WriteImage(clone_info, image, exception);
                if (status != MagickFalse)
                  {
                    ssize_t
                      count;

                    count = FormatImageFilename(clone_info, image, clone_info->filename,
                                                MagickPathExtent, exception);
                    if (count <= 0)
                      status = MagickFalse;
                  }
              }
            if (status != MagickFalse)
              {
                Image
                  *image_list;

                image_list = CloneImageList(image, exception);
                if (image_list != (Image *) NULL)
                  {
                    status = WriteImages(clone_info, image_list,
                                         clone_info->filename, exception);
                    image_list = DestroyImageList(image_list);
                  }
              }
            if (status == MagickFalse)
              {
                image->exception->severity = WarningException;
                CloneString(&image->exception->message, "unable to write image");
              }
          }
        image = next;
      }
      images = images_head;
    }
  else
    {
      Image
        *image_list;

      clone_info->adjoin = MagickTrue;
      image_list = CloneImageList(images, exception);
      if (image_list != (Image *) NULL)
        {
          status = WriteImage(clone_info, image_list, exception);
          image_list = DestroyImageList(image_list);
        }
    }
  clone_info = DestroyImageInfo(clone_info);
  return(status);
}
